/**
 * Generates the module indexes by globbing src/modules/<id>/:
 *  - _generated.ts         ← module.ts (manifests; safe for client + server)
 *  - _generated.server.ts  ← export.server.ts (server-only export section builders)
 * Adding a module = creating a folder. Never edit the generated files by hand.
 */
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(process.cwd(), "src", "modules");
const dirs = readdirSync(root, { withFileTypes: true })
  .filter((d) => d.isDirectory() && !d.name.startsWith("_"))
  .map((d) => d.name)
  .sort();
const ident = (name: string) => "m_" + name.replace(/[^a-zA-Z0-9]/g, "_");

function write(file: string, content: string, label: string) {
  const target = join(root, file);
  const prev = existsSync(target) ? readFileSync(target, "utf8") : "";
  if (prev !== content) {
    writeFileSync(target, content);
    console.log(`[acc] ${label}`);
  }
}

const withModule = dirs.filter((n) => existsSync(join(root, n, "module.ts")));
write(
  "_generated.ts",
  `// AUTO-GENERATED by scripts/gen-module-index.ts — do not edit.
import type { AccModule } from "./types";
${withModule.map((d) => `import ${ident(d)} from "./${d}/module";`).join("\n")}

export const discoveredModules: AccModule[] = [${withModule.map(ident).join(", ")}];
`,
  `module index: ${withModule.length} modules (${withModule.join(", ")})`,
);

const withExports = dirs.filter((n) => existsSync(join(root, n, "export.server.ts")));
write(
  "_generated.server.ts",
  `// AUTO-GENERATED by scripts/gen-module-index.ts — do not edit.
import "server-only";
import type { SectionBuilders } from "@/lib/export/builder-types";
${withExports.map((d) => `import { builders as ${ident(d)} } from "./${d}/export.server";`).join("\n")}

export const discoveredBuilders: SectionBuilders = { ${withExports.map((d) => `...${ident(d)}`).join(", ")} };
`,
  `export builders: ${withExports.length} modules`,
);

// Enrichers: one folder per public source, src/lib/enrich/enrichers/<id>/index.ts (default export).
const enrichRoot = join(process.cwd(), "src", "lib", "enrich", "enrichers");
const enrichDirs = existsSync(enrichRoot)
  ? readdirSync(enrichRoot, { withFileTypes: true })
      .filter(
        (d) =>
          d.isDirectory() &&
          !d.name.startsWith("_") &&
          existsSync(join(enrichRoot, d.name, "index.ts")),
      )
      .map((d) => d.name)
      .sort()
  : [];
const enrichTarget = join(enrichRoot, "_generated.ts");
const enrichContent = `// AUTO-GENERATED by scripts/gen-module-index.ts — do not edit.
import type { Enricher } from "../types";
${enrichDirs.map((d) => `import ${ident(d)} from "./${d}";`).join("\n")}

export const discoveredEnrichers: Enricher[] = [${enrichDirs.map(ident).join(", ")}];
`;
if (
  existsSync(enrichRoot) &&
  (!existsSync(enrichTarget) || readFileSync(enrichTarget, "utf8") !== enrichContent)
) {
  writeFileSync(enrichTarget, enrichContent);
  console.log(`[acc] enrichers: ${enrichDirs.length} (${enrichDirs.join(", ")})`);
}
